  ProgramStateRef State = C.getState();

  // Find the rounding expression in this bind, including macro-expanded forms
  // that do not retain a named CallExpr in the AST.
  const CallExpr *CE = findSpecificTypeInChildren<CallExpr>(S);
  if (CE && isRoundupPow2Call(CE, C)) {
    State = State->set<RoundupResMap>(LReg, CE);
  } else if (ExprHasName(S, "roundup_pow_of_two", C)) {
    State = State->set<RoundupResMap>(LReg, S);
  } else {
